ep_output_t out;
ep_mode_t cur;
adcs_vec3_t sun_hat;
double axial = 0.0, cross = 0.0;
int fault = 0;
int eclipse = 0;
adcs_status_t nrm;

out.mode = EP_FAULT;
out.elapsed = 0U;
out.payload_on = 0;
out.heater_on = 0;
out.axial_m = 0.0;
out.cross_track_m = 0.0;

if ((ep_input.enable != 0) && (ep_input.enable != 1)) {
    fault = 1;
}

if ((ep_input.position_eci_m == NULL) || (ep_input.sun_direction_eci == NULL)) {
    fault = 1;
} else if ((!adcs_is_finite_vec3(ep_input.position_eci_m)) ||
           (!adcs_is_finite_vec3(ep_input.sun_direction_eci))) {
    fault = 1;
}

if ((!isfinite(ep_config.earth_radius_m)) || (!(ep_config.earth_radius_m > 0.0))) fault = 1;
if ((ep_config.recovery_cycles < 1U) || (ep_config.recovery_cycles > 100U)) fault = 1;
if ((ep_config.warmup_cycles < 1U) || (ep_config.warmup_cycles > 100U)) fault = 1;
if ((!isfinite(ep_input.battery_soc)) || (ep_input.battery_soc < 0.0) || (ep_input.battery_soc > 1.0)) fault = 1;
if ((!isfinite(ep_config.payload_on_soc)) || (ep_config.payload_on_soc < 0.0) || (ep_config.payload_on_soc > 1.0)) fault = 1;
if ((!isfinite(ep_config.payload_off_soc)) || (ep_config.payload_off_soc < 0.0) || (ep_config.payload_off_soc > 1.0)) fault = 1;
if (ep_config.payload_off_soc > ep_config.payload_on_soc) fault = 1;
if ((ep_state.mode < EP_SUN) || (ep_state.mode > EP_LOADSHED)) fault = 1;

if (fault || (ep_state.mode == EP_FAULT)) {
    ep_state.mode = EP_FAULT;
    ep_state.elapsed = 0U;
    out.mode = EP_FAULT;
    out.elapsed = 0U;
    out.payload_on = 0;
    out.heater_on = 0;
    ep_output = out;
    return;
}

nrm = adcs_vec3_normalize(ep_input.sun_direction_eci, ADCS_EPS_NORM, &sun_hat);
if (nrm != ADCS_OK) {
    ep_state.mode = EP_FAULT;
    ep_state.elapsed = 0U;
    out.mode = EP_FAULT;
    out.elapsed = 0U;
    out.payload_on = 0;
    out.heater_on = 0;
    ep_output = out;
    return;
}

axial = adcs_vec3_dot(ep_input.position_eci_m, &sun_hat);
{
    adcs_vec3_t par = adcs_vec3_scale(&sun_hat, axial);
    adcs_vec3_t perp = adcs_vec3_sub(ep_input.position_eci_m, &par);
    cross = adcs_vec3_norm(&perp);
}

out.axial_m = axial;
out.cross_track_m = cross;

eclipse = (axial < 0.0) && (cross < ep_config.earth_radius_m);

cur = ep_state.mode;

/* disabled */
if (ep_input.enable == 0) {
    ep_state.mode = EP_SUN;
    ep_state.elapsed = 0U;
    out.mode = EP_SUN;
    out.elapsed = 0U;
    out.payload_on = 0;
    out.heater_on = 0;
    ep_output = out;
    return;
}

/* eclipse 优先 */
if (eclipse) {
    ep_state.mode = EP_ECLIPSE;
    ep_state.elapsed = 0U;
    out.mode = EP_ECLIPSE;
    out.elapsed = 0U;
    out.payload_on = 0;
    out.heater_on = 1;
    ep_output = out;
    return;
}

/* 阳光 */
if (cur == EP_ECLIPSE) {
    ep_state.mode = EP_RECOVERY;
    ep_state.elapsed = 1U;
    out.mode = EP_RECOVERY;
    out.elapsed = 1U;
    out.payload_on = 0;
    out.heater_on = 1;
} else if (cur == EP_RECOVERY) {
    unint32 e = ep_state.elapsed + 1U;
    if (e >= ep_config.recovery_cycles) {
        ep_state.mode = EP_WARMUP;
        ep_state.elapsed = 1U;
        out.mode = EP_WARMUP;
        out.elapsed = 1U;
    } else {
        ep_state.elapsed = e;
        out.mode = EP_RECOVERY;
        out.elapsed = e;
    }
    out.payload_on = 0;
    out.heater_on = 1;
} else if (cur == EP_WARMUP) {
    unint32 e = ep_state.elapsed + 1U;
    if (e >= ep_config.warmup_cycles) {
        ep_state.elapsed = ep_config.warmup_cycles;
        out.elapsed = ep_config.warmup_cycles;
        if (ep_input.battery_soc >= ep_config.payload_on_soc) {
            ep_state.mode = EP_SUN;
            out.mode = EP_SUN;
            out.payload_on = 1;
        } else {
            ep_state.mode = EP_LOADWAIT;
            out.mode = EP_LOADWAIT;
            out.payload_on = 0;
        }
    } else {
        ep_state.elapsed = e;
        out.mode = EP_WARMUP;
        out.elapsed = e;
        out.payload_on = 0;
    }
    out.heater_on = 1;
} else if (cur == EP_LOADWAIT) {
    if (ep_input.battery_soc >= ep_config.payload_on_soc) {
        ep_state.mode = EP_SUN;
        out.mode = EP_SUN;
        out.payload_on = 1;
    } else {
        ep_state.mode = EP_LOADWAIT;
        out.mode = EP_LOADWAIT;
        out.payload_on = 0;
    }
    out.elapsed = ep_state.elapsed;
    out.heater_on = 1;
} else if (cur == EP_SUN) {
    if (ep_input.battery_soc < ep_config.payload_off_soc) {
        ep_state.mode = EP_LOADSHED;
        out.mode = EP_LOADSHED;
        out.payload_on = 0;
    } else {
        ep_state.mode = EP_SUN;
        out.mode = EP_SUN;
        out.payload_on = 1;
    }
    out.elapsed = ep_state.elapsed;
    out.heater_on = 1;
} else if (cur == EP_LOADSHED) {
    if (ep_input.battery_soc >= ep_config.payload_on_soc) {
        ep_state.mode = EP_SUN;
        out.mode = EP_SUN;
        out.payload_on = 1;
    } else {
        ep_state.mode = EP_LOADSHED;
        out.mode = EP_LOADSHED;
        out.payload_on = 0;
    }
    out.elapsed = ep_state.elapsed;
    out.heater_on = 1;
} else {
    ep_state.mode = EP_FAULT;
    ep_state.elapsed = 0U;
    out.mode = EP_FAULT;
    out.elapsed = 0U;
    out.payload_on = 0;
    out.heater_on = 0;
}

ep_output = out;

