const adcs_vec3_t *pos = ep_input.position_eci_m;
const adcs_vec3_t *sun = ep_input.sun_direction_eci;
adcs_vec3_t sun_n;
double axial = 0.0, cross_track = 0.0;
double dist2, proj2;
int eclipse_flag = 0;
adcs_status_t ns;

ep_output.payload_on = 0;
ep_output.heater_on = 0;
ep_output.axial_m = 0.0;
ep_output.cross_track_m = 0.0;

/* ---- FAULT validation ---- */
if ((pos == NULL) || (sun == NULL) || (!adcs_is_finite_vec3(pos)) ||
    (!adcs_is_finite_vec3(sun)) || (!isfinite(ep_config.earth_radius_m)) ||
    (ep_config.earth_radius_m <= 0.0) ||
    (ep_config.recovery_cycles < 1U) || (ep_config.recovery_cycles > 100U) ||
    (ep_config.warmup_cycles < 1U) || (ep_config.warmup_cycles > 100U) ||
    (!isfinite(ep_input.battery_soc)) || (ep_input.battery_soc < 0.0) ||
    (ep_input.battery_soc > 1.0) ||
    (!isfinite(ep_config.payload_on_soc)) || (ep_config.payload_on_soc < 0.0) ||
    (ep_config.payload_on_soc > 1.0) ||
    (!isfinite(ep_config.payload_off_soc)) || (ep_config.payload_off_soc < 0.0) ||
    (ep_config.payload_off_soc > 1.0) ||
    (ep_config.payload_off_soc > ep_config.payload_on_soc) ||
    ((ep_input.enable != 0) && (ep_input.enable != 1))) {
    ep_state.mode = EP_FAULT;
    ep_state.elapsed = 0U;
    ep_output.mode = EP_FAULT;
    ep_output.elapsed = 0U;
    return;
}

/* ---- compute axial / cross_track (every call) ---- */
ns = adcs_vec3_normalize(sun, ADCS_EPS_NORM, &sun_n);
if (ns != ADCS_OK) {
    ep_state.mode = EP_FAULT;
    ep_state.elapsed = 0U;
    ep_output.mode = EP_FAULT;
    ep_output.elapsed = 0U;
    return;
}
axial = adcs_vec3_dot(pos, &sun_n);
dist2 = adcs_vec3_dot(pos, pos);
proj2 = axial * axial;
if (dist2 > proj2)
    cross_track = sqrt(dist2 - proj2);
else
    cross_track = 0.0;
ep_output.axial_m = axial;
ep_output.cross_track_m = cross_track;

if ((axial < 0.0) && (cross_track < ep_config.earth_radius_m))
    eclipse_flag = 1;

/* ---- disabled ---- */
if (ep_input.enable == 0) {
    ep_state.mode = EP_SUN;
    ep_state.elapsed = 0U;
    ep_output.mode = EP_SUN;
    ep_output.elapsed = 0U;
    return;
}

/* ---- eclipse preempts every sunlight phase ---- */
if (eclipse_flag) {
    ep_state.mode = EP_ECLIPSE;
    ep_state.elapsed = 0U;
    ep_output.mode = EP_ECLIPSE;
    ep_output.elapsed = 0U;
    ep_output.heater_on = 1;
    return;
}

/* ---- sunlight phases ---- */
switch (ep_state.mode) {
case EP_ECLIPSE:
    ep_state.mode = EP_RECOVERY;
    ep_state.elapsed = 1U;
    break;

case EP_RECOVERY:
    if (ep_state.elapsed < ep_config.recovery_cycles) {
        ep_state.elapsed += 1U;
    } else {
        ep_state.mode = EP_WARMUP;
        ep_state.elapsed = 1U;
    }
