{
    double pos_x, pos_y, pos_z, sun_x, sun_y, sun_z, nrm;
    double axial, perp_x, perp_y, perp_z, cross_track;
    adcs_vec3_t sun_unit;
    int valid;
    uint32_t recov, warm;
    double on_soc, off_soc, rad;

    /* default outputs */
    ep_output.mode = ep_state.mode;
    ep_output.elapsed = ep_state.elapsed;
    ep_output.payload_on = 0;
    ep_output.heater_on = 0;
    ep_output.axial_m = 0.0;
    ep_output.cross_track_m = 0.0;

    /* 1) enable validity */
    if ((ep_input.enable != 0) && (ep_input.enable != 1)) {
        ep_state.mode = EP_FAULT;
        ep_state.elapsed = 0U;
        ep_output.mode = EP_FAULT;
        ep_output.elapsed = 0U;
        ep_output.payload_on = 0;
        ep_output.heater_on = 0;
        return;
    }

    /* 2) disable */
    if (ep_input.enable == 0) {
        ep_state.mode = EP_SUN;
        ep_state.elapsed = 0U;
        ep_output.mode = EP_SUN;
        ep_output.elapsed = 0U;
        ep_output.payload_on = 0;
        ep_output.heater_on = 0;
        return;
    }

    /* 3) config validity */
    valid = 1;
    if ((ep_input.position_eci_m == NULL) || (ep_input.sun_direction_eci == NULL)) valid = 0;
    if (valid && (!adcs_is_finite_vec3(ep_input.position_eci_m))) valid = 0;
    if (valid && (!adcs_is_finite_vec3(ep_input.sun_direction_eci))) valid = 0;
    rad = ep_config.earth_radius_m;
    if (valid && ((!isfinite(rad)) || (rad <= 0.0))) valid = 0;
    if (valid && ((ep_config.recovery_cycles < 1U) || (ep_config.recovery_cycles > 100U))) valid = 0;
    if (valid && ((ep_config.warmup_cycles < 1U) || (ep_config.warmup_cycles > 100U))) valid = 0;
    on_soc = ep_config.payload_on_soc;
    off_soc = ep_config.payload_off_soc;
    if (valid && ((!isfinite(on_soc)) || (on_soc < 0.0) || (on_soc > 1.0))) valid = 0;
    if (valid && ((!isfinite(off_soc)) || (off_soc < 0.0) || (off_soc > 1.0))) valid = 0;
    if (valid && (off_soc > on_soc)) valid = 0;
    if (valid && ((!isfinite(ep_input.battery_soc)) || (ep_input.battery_soc < 0.0) ||
                  (ep_input.battery_soc > 1.0)))
        valid = 0;

    if (!valid) {
        ep_state.mode = EP_FAULT;
        ep_state.elapsed = 0U;
        ep_output.mode = EP_FAULT;
        ep_output.elapsed = 0U;
        ep_output.payload_on = 0;
        ep_output.heater_on = 0;
        return;
    }

    /* 4) normalize sun direction */
    if (adcs_vec3_normalize(ep_input.sun_direction_eci, ADCS_EPS_NORM, &sun_unit) != ADCS_OK) {
        ep_state.mode = EP_FAULT;
        ep_state.elapsed = 0U;
        ep_output.mode = EP_FAULT;
        ep_output.elapsed = 0U;
        ep_output.payload_on = 0;
        ep_output.heater_on = 0;
        return;
    }
    sun_x = sun_unit.x;
    sun_y = sun_unit.y;
    sun_z = sun_unit.z;

    /* 5) geometry */
    pos_x = ep_input.position_eci_m->x;
    pos_y = ep_input.position_eci_m->y;
    pos_z = ep_input.position_eci_m->z;
    axial = pos_x * sun_x + pos_y * sun_y + pos_z * sun_z;
    perp_x = pos_x - axial * sun_x;
    perp_y = pos_y - axial * sun_y;
    perp_z = pos_z - axial * sun_z;
    nrm = perp_x * perp_x + perp_y * perp_y + perp_z * perp_z;
    cross_track = sqrt(nrm);
    ep_output.axial_m = axial;
    ep_output.cross_track_m = cross_track;

    recov = ep_config.recovery_cycles;
    warm = ep_config.warmup_cycles;

    /* 6) eclipse preemption */
    if ((axial < 0.0) && (cross_track < rad)) {
        ep_state.mode = EP_ECLIPSE;
        ep_state.elapsed = 0U;
        ep_output.mode = EP_ECLIPSE;
        ep_output.elapsed = 0U;
        ep_output.payload_on = 0;
        ep_output.heater_on = 1;
        return;
    }

    /* 7) sunlight state machine */
    switch (ep_state.mode) {
    case EP_ECLIPSE:
        ep_state.mode = EP_RECOVERY;
        ep_state.elapsed = 1U;
        ep_output.mode = EP_RECOVERY;
        ep_output.elapsed = 1U;
        ep_output.payload_on = 0;
        ep_output.heater_on = 0;
        break;

    case EP_RECOVERY:
        if (ep_state.elapsed < recov) {
            ep_state.elapsed = ep_state.elapsed + 1U;
            ep_output.mode = EP_RECOVERY;
            ep_output.elapsed = ep_state.elapsed;
            ep_output.payload_on = 0;
            ep_output.heater_on = 0;
        } else {
            ep_state.mode = EP_WARMUP;
            ep_state.elapsed = 1U;
            ep_output.mode = EP_WARMUP;
            ep_output.elapsed = 1U;
            ep_output.payload_on = 0;
            ep_output.heater_on = 0;
        }
        break;

    case EP_WARMUP:
        if (ep_state.elapsed < warm) {
            ep_state.elapsed = ep_state.elapsed + 1U;
            ep_output.mode = EP_WARMUP;
            ep_output.elapsed = ep_state.elapsed;
            ep_output.payload_on = 0;
            ep_output.heater_on = 0;
        } else {
            if (ep_input.battery_soc >= on_soc) {
                ep_state.mode = EP_SUN;
                ep_state.elapsed = 0U;
                ep_output.mode = EP_SUN;
                ep_output.elapsed = 0U;
                ep_output.payload_on = 1;
                ep_output.heater_on = 0;
            } else {
                ep_state.mode = EP_LOADWAIT;
                ep_state.elapsed = 0U;
                ep_output.mode = EP_LOADWAIT;
                ep_output.elapsed = 0U;
                ep_output.payload_on = 0;
                ep_output.heater_on = 0;
            }
        }
        break;

    case EP_LOADWAIT:
        if (ep_input.battery_soc >= on_soc) {
            ep_state.mode = EP_SUN;
            ep_state.elapsed = 0U;
            ep_output.mode = EP_SUN;
            ep_output.elapsed = 0U;
            ep_output.payload_on = 1;
            ep_output.heater_on = 0;
        } else {
            ep_output.mode = EP_LOADWAIT;
            ep_output.elapsed = ep_state.elapsed;
            ep_output.payload_on = 0;
            ep_output.heater_on = 0;
        }
        break;

    case EP_SUN:
        if (ep_input.battery_soc < off_soc) {
            ep_state.mode = EP_LOADSHED;
            ep_state.elapsed = 0U;
            ep_output.mode = EP_LOADSHED;
            ep_output.elapsed = 0U;
            ep_output.payload_on = 0;
            ep_output.heater_on = 0;
        } else {
            ep_output.mode = EP_SUN;
            ep_output.elapsed = ep_state.elapsed;
            ep_output.payload_on = 1;
            ep_output.heater_on = 0;
        }
        break;

    case EP_LOADSHED:
        if (ep_input.battery_soc >= on_soc) {
            ep_state.mode = EP_SUN;
            ep_state.elapsed = 0U;
            ep_output.mode = EP_SUN;
            ep_output.elapsed = 0U;
            ep_output.payload_on = 1;
            ep_output.heater_on = 0;
        } else {
            ep_output.mode = EP_LOADSHED;
            ep_output.elapsed = ep_state.elapsed;
            ep_output.payload_on = 0;
            ep_output.heater_on = 0;
        }
        break;

    case EP_FAULT:
        ep_state.elapsed = 0U;
        ep_output.mode = EP_FAULT;
        ep_output.elapsed = 0U;
        ep_output.payload_on = 0;
        ep_output.heater_on = 0;
        break;

